widget.starter:
#include <cmath>
#include <vector>

double annualised_vol(const std::vector<double>& prices) {
    // 1. daily log returns
    // 2. their sample standard deviation (divide by n - 1)
    // 3. scale by sqrt(252)
    return 0;
}

widget.solution:
#include <cmath>
#include <vector>

double annualised_vol(const std::vector<double>& prices) {
    std::vector<double> r;
    for (size_t i = 1; i < prices.size(); ++i)
        r.push_back(std::log(prices[i] / prices[i - 1]));
    double mean = 0;
    for (double x : r) mean += x;
    mean /= r.size();
    double ss = 0;
    for (double x : r) ss += (x - mean) * (x - mean);
    return std::sqrt(ss / (r.size() - 1)) * std::sqrt(252.0);
}

