#include <cmath>

double bs_d1(double s, double k, double r, double sigma, double t) {
    return 0;
}

widget.solution:
#include <cmath>

double bs_d1(double s, double k, double r, double sigma, double t) {
    return (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
}

